// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ERCDDAToken} from "../src/ERCDDAToken.sol";

contract InvMutTest is Test {
    ERCDDAToken c;
    function setUp() public { c = new ERCDDAToken(0, "token", "TKN"); }
    function testFuzz_property(address nonOwner, uint256 burnAmount) public {
        vm.assume(nonOwner != address(0));
        vm.assume(nonOwner != address(this));

        vm.prank(address(this));
        c.mintToken(nonOwner, burnAmount);

        vm.prank(nonOwner);
        bool ok = true;
        try c.burn(burnAmount) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(!ok);
    }
}
